 * Normalise a loan row into the public shape.
 * @param {{id: number|string, bookId: number|string, userId: string, status: string}} row
 */
function toLoan(row) {
  return {
    id: row.id,
    bookId: row.bookId,
    userId: row.userId,
    status: row.status,
  };
}

module.exports = {
  RepositoryError,
  assertBookInput,
  toBook,
  toLoan,
};"}

