'use strict';

/**
 * Repository interface (contract) shared by the PostgreSQL and in-memory
 * adapters. Every concrete repository must implement all methods below.
 *
 * This module also provides a small set of domain/validation helpers so both
 * adapters (and the business modules that consume them) agree on shapes and
 * error semantics. Business modules depend only on this interface plus the
 * concrete adapter injected at runtime; tests inject the in-memory adapter.
 */

/**
 * Result shape returned by createBook:
 *   { id, title, availableCopies }
 *
 * Result shape returned by listBooks:
 *   Array<{ id, title, availableCopies }>
 *
 * Result shape returned by getBook:
 *   { id, title, availableCopies } | null
 *
 * Result shape returned by createLoan (via borrow):
 *   { id, bookId, userId, status: 'active' }
 *
 * Result shape returned by listLoans / getLoan:
 *   { id, bookId, userId, status }
 *
 * A repository implementation must export an object (class instance or
 * plain object) exposing:
 *
 *   createBook({ title, copies })        -> { id, title, availableCopies }
 *   listBooks()                           -> Array<book>
 *   getBook(id)                           -> book | null
 *   borrow(bookId, userId)               -> { id, bookId, userId, status } or throw
 *   listLoans()                           -> Array<loan>
 *   getLoan(id)                           -> loan | null
 *   returnLoan(id)                        -> loan with status 'returned' or throw
 *
 * Semantics (kept identical across adapters):
 *   - borrow throws a typed error when no remaining stock or a duplicate
 *     active loan exists (caller maps to 409).
 *   - returnLoan is idempotent: returning an already-returned loan does not
 *     restore stock a second time.
 */

class RepositoryError extends Error {
  /**
   * @param {string} code - stable machine code ('NOT_FOUND', 'NO_STOCK',
   *   'DUPLICATE_LOAN', 'INVALID_STATE').
   * @param {string} message - human-readable message.
   * @param {number} [httpStatus] - suggested HTTP status.
   */
  constructor(code, message, httpStatus) {
    super(message);
    this.name = 'RepositoryError';
    this.code = code;
    this.httpStatus = httpStatus;
  }
}

/**
 * Validate fields shared by both adapters so behaviour is consistent.
 *
 * @param {string} title
 * @param {*} copies
 */
function assertBookInput(title, copies) {
  if (typeof title !== 'string' || title.trim() === '') {
    throw new RepositoryError('INVALID_TITLE', 'Title must be a non-empty string', 400);
  }
  if (!Number.isInteger(copies) || copies <= 0) {
    throw new RepositoryError('INVALID_COPIES', 'Copies must be a positive integer', 400);
  }
}

/**
 * Normalise a book row (internal storage) into the public shape.
 * @param {{id: number|string, title: string, copies: number}} row
 */
function toBook(row) {
  return {
    id: row.id,
    title: row.title,
    availableCopies: row.copies,
  };
}

/**
 * Normalise a loan row into the public shape.
 * @param {{id: number|string, bookId: number|string, userId: string, status: string}} row
 */
function toLoan(row) {
  return {
    id: row.id,
    bookId: row.bookId,
    userId: row.userId,
    status: row.status,
  };
}

module.exports = {
  RepositoryError,
  assertBookInput,
  toBook,
  toLoan,
};

'use strict';

/**
 * In-memory repository implementing the shared repository contract in
 * src/repository.js. Intended for unit/API tests so npm test runs without a
 * live PostgreSQL. Behaviour (validation, error codes, idempotent returns)
 * mirrors the PostgreSQL adapter so the business modules and routes are
 * exercised identically.
 */

const {
  RepositoryError,
  assertBookInput,
  toBook,
  toLoan,
} = require('./repository');

class MemoryRepository {
  constructor() {
    this.books = new Map(); // id -> { id, title, copies }
    this.loans = new Map(); // id -> { id, bookId, userId, status }
    this.nextBookId = 1;
    this.nextLoanId = 1;
  }

  createBook({ title, copies }) {
    assertBookInput(title, copies);
    const id = this.nextBookId++;
    const row = { id, title, copies };
    this.books.set(id, row);
    return toBook(row);
  }

  listBooks() {
    return [...this.books.values()].sort((a, b) => a.id - b.id).map(toBook);
  }

  getBook(id) {
    const row = this.books.get(Number(id));
    return row == null ? null : toBook(row);
  }

  borrow(bookId, userId) {
    if (typeof userId !== 'string' || userId.trim() === '') {
      throw new RepositoryError('INVALID_USER_ID', 'userId must be a non-empty string', 400);
    }

    const book = this.books.get(Number(bookId));
    if (book == null) {
      throw new RepositoryError('NOT_FOUND', 'Book not found', 404);
    }
    if (book.copies <= 0) {
      throw new RepositoryError('NO_STOCK', 'No available copies', 409);
    }

    for (const loan of this.loans.values()) {
      if (loan.bookId === book.id && loan.userId === userId && loan.status === 'active') {
        throw new RepositoryError('DUPLICATE_LOAN', 'Reader already has an active loan', 409);
      }
    }

    const id = this.nextLoanId++;
    const loan = { id, bookId: book.id, userId, status: 'active' };
    this.loans.set(id, loan);
    book.copies -= 1;
    return toLoan(loan);
  }

  listLoans() {
    return [...this.loans.values()].sort((a, b) => a.id - b.id).map(toLoan);
  }

  getLoan(id) {
    const row = this.loans.get(Number(id));
    return row == null ? null : toLoan(row);
  }

  returnLoan(id) {
    const loan = this.loans.get(Number(id));
    if (loan == null) {
      throw new RepositoryError('NOT_FOUND', 'Loan not found', 404);
    }

    if (loan.status === 'returned') {
      return toLoan(loan);
    }

    loan.status = 'returned';
    const book = this.books.get(loan.bookId);
    if (book != null) {
      book.copies += 1;
    }
    return toLoan(loan);
  }
}

module.exports = { MemoryRepository };

'use strict';

/**
 * PostgreSQL repository implementing the shared repository contract in
 * src/repository.js. Borrowing and returning run inside a transaction on a
 * single client with row locks so concurrent borrowers cannot push available
 * copies below zero and concurrent returns never restore stock more than once.
 */

const {
  RepositoryError,
  assertBookInput,
  toBook,
  toLoan,
} = require('./repository');

const BOOK_COLUMNS = 'id, title, copies';

function rowToBook(row) {
  return toBook(row);
}

function rowToLoan(row) {
  return toLoan({
    id: row.id,
    bookId: row.book_id,
    userId: row.user_id,
    status: row.status,
  });
}

class PgRepository {
  /**
   * @param {import('pg').Pool} pool - PostgreSQL connection pool.
   */
  constructor(pool) {
    this.pool = pool;
  }

  async createBook({ title, copies }) {
    assertBookInput(title, copies);
    try {
      const result = await this.pool.query(
        'INSERT INTO books (title, copies) VALUES ($1, $2) RETURNING ' + BOOK_COLUMNS,
        [title, copies]
      );
      return rowToBook(result.rows[0]);
    } catch (err) {
      if (err.code === '23514') {
        throw new RepositoryError('INVALID_COPIES', 'Copies must be a positive integer', 400);
      }
      throw err;
    }
  }

  async listBooks() {
    const result = await this.pool.query(
      'SELECT ' + BOOK_COLUMNS + ' FROM books ORDER BY id'
    );
    return result.rows.map(rowToBook);
  }

  async getBook(id) {
    const result = await this.pool.query(
      'SELECT ' + BOOK_COLUMNS + ' FROM books WHERE id = $1',
      [id]
    );
    return result.rows.length === 0 ? null : rowToBook(result.rows[0]);
  }

  /**
   * Borrow one available copy for a reader. Uses a transaction and FOR UPDATE
   * row lock on the book to serialise concurrent borrowers.
   */
  async borrow(bookId, userId) {
    if (typeof userId !== 'string' || userId.trim() === '') {
      throw new RepositoryError('INVALID_USER_ID', 'userId must be a non-empty string', 400);
    }

    const client = await this.pool.connect();
    try {
      await client.query('BEGIN');

      const bookResult = await client.query(
        'SELECT id, title, copies FROM books WHERE id = $1 FOR UPDATE',
        [bookId]
      );
      if (bookResult.rows.length === 0) {
        throw new RepositoryError('NOT_FOUND', 'Book not found', 404);
      }
      const book = bookResult.rows[0];

      if (book.copies <= 0) {
        throw new RepositoryError('NO_STOCK', 'No available copies', 409);
      }

      const duplicate = await client.query(
        "SELECT id FROM loans WHERE book_id = $1 AND user_id = $2 AND status = 'active'",
        [bookId, userId]
      );
      if (duplicate.rows.length > 0) {
        throw new RepositoryError('DUPLICATE_LOAN', 'Reader already has an active loan', 409);
      }

      const loanResult = await client.query(
        "INSERT INTO loans (book_id, user_id, status) VALUES ($1, $2, 'active') RETURNING id, book_id, user_id, status",
        [bookId, userId]
      );

      await client.query('UPDATE books SET copies = copies - 1 WHERE id = $1', [bookId]);

      await client.query('COMMIT');
      return rowToLoan(loanResult.rows[0]);
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  }

  async listLoans() {
    const result = await this.pool.query(
      'SELECT id, book_id, user_id, status FROM loans ORDER BY id'
    );
    return result.rows.map(rowToLoan);
  }

  async getLoan(id) {
    const result = await this.pool.query(
      'SELECT id, book_id, user_id, status FROM loans WHERE id = $1',
      [id]
    );
    return result.rows.length === 0 ? null : rowToLoan(result.rows[0]);
  }

  /**
   * Return a loan. Idempotent: returning an already-returned loan leaves stock
   * untouched. The transition from active -> returned increments stock exactly
   * once inside a transaction with a row lock.
   */
  async returnLoan(id) {
    const client = await this.pool.connect();
    try {
      await client.query('BEGIN');

      const loanResult = await client.query(
        'SELECT id, book_id, user_id, status FROM loans WHERE id = $1 FOR UPDATE',
        [id]
      );
      if (loanResult.rows.length === 0) {
        throw new RepositoryError('NOT_FOUND', 'Loan not found', 404);
      }
      const loan = loanResult.rows[0];

      if (loan.status === 'returned') {
        await client.query('COMMIT');
        return rowToLoan(loan);
      }

      await client.query(
        "UPDATE loans SET status = 'returned', returned_at = now() WHERE id = $1",
        [id]
      );
      await client.query('UPDATE books SET copies = copies + 1 WHERE id = $1', [loan.book_id]);

      await client.query('COMMIT');

      const updated = await this.pool.query(
        'SELECT id, book_id, user_id, status FROM loans WHERE id = $1',
        [id]
      );
      return rowToLoan(updated.rows[0]);
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  }
}

module.exports = { PgRepository };

'use strict';

/**
 * PostgreSQL schema bootstrap for the library borrowing application.
 *
 * Idempotent: CREATE TABLE IF NOT EXISTS so repeated startup never fails.
 * Seed data is inserted only when the books table is empty, so user-created
 * books are preserved across restarts.
 */

const SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS books (
  id BIGSERIAL PRIMARY KEY,
  title TEXT NOT NULL,
  copies INTEGER NOT NULL CHECK (copies >= 0)
);

CREATE TABLE IF NOT EXISTS loans (
  id BIGSERIAL PRIMARY KEY,
  book_id BIGINT NOT NULL REFERENCES books(id),
  user_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('active', 'returned')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  returned_at TIMESTAMPTZ
);

CREATE UNIQUE INDEX IF NOT EXISTS loans_active_unique
  ON loans (book_id, user_id)
  WHERE status = 'active';
`;

const SEED_BOOKS = [
  { title: 'The Great Gatsby', copies: 3 },
  { title: '1984', copies: 2 },
  { title: 'To Kill a Mockingbird', copies: 1 },
];

/**
 * Create tables and indexes idempotently, then seed books only when empty.
 *
 * @param {import('pg').Pool} pool - PostgreSQL connection pool.
 */
async function bootstrap(pool) {
  await pool.query(SCHEMA_SQL);

  const existing = await pool.query('SELECT COUNT(*)::int AS count FROM books');
  if (existing.rows[0].count > 0) {
    return;
  }

  for (const book of SEED_BOOKS) {
    await pool.query('INSERT INTO books (title, copies) VALUES ($1, $2)', [
      book.title,
      book.copies,
    ]);
  }
}

module.exports = { bootstrap, SEED_BOOKS };

