'use strict';

/**
 * Gateway entrypoint.
 *
 * Connects to PostgreSQL via a connection pool, runs the idempotent schema
 * bootstrap, serves the browser UI at / and the REST API, and exposes /health.
 * Connection settings are driven by environment variables (.env).
 */

const path = require('node:path');
const express = require('express');
const { Pool } = require('pg');
const { createApp } = require('./app');
const { PgRepository } = require('./pgRepository');
const { bootstrap } = require('./schema');

const PORT = Number(process.env.PORT) || 3000;

function createPool() {
  return new Pool({
    host: process.env.PGHOST || 'postgres',
    port: Number(process.env.PGPORT) || 5432,
    database: process.env.PGDATABASE || 'library',
    user: process.env.PGUSER || 'library',
    password: process.env.PGPASSWORD || 'library',
  });
}

async function main() {
  const pool = createPool();

  // Idempotent schema bootstrap; seeds only when the books table is empty so
  // repeated startup never overwrites user-created books.
  await bootstrap(pool);

  const repository = new PgRepository(pool);
  const app = createApp(repository);

  // Serve browser UI at /.
  const publicDir = path.join(__dirname, '..', 'public');
  app.use(express.static(publicDir));

  const server = app.listen(PORT, () => {
    // eslint-disable-next-line no-console
    console.log(`Library gateway listening on port ${PORT}`);
  });

  const shutdown = async () => {
    server.close(async () => {
      await pool.end();
      process.exit(0);
    });
  };

  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);

  return { app, server, pool };
}

if (require.main === module) {
  main().catch((err) => {
    // eslint-disable-next-line no-console
    console.error('Failed to start gateway:', err);
    process.exit(1);
  });
}

module.exports = { main, createPool };

'use strict';

/**
 * Express application factory.
 *
 * Wires the REST endpoints described in the architecture document to the
 * catalog and loans business modules. The factory takes a repository
 * (dependency injection) so tests can inject the in-memory adapter while the
 * runtime (`src/server.js`) supplies the real PostgreSQL adapter.
 *
 * Endpoint mapping (Architecture_Documentation.md, REST interface):
 *   POST   /api/books          -> 201 {id,title,availableCopies} | 400
 *   GET    /api/books          -> 200 {books:[...]}
 *   GET    /api/books/:id      -> 200 book | 404
 *   POST   /api/loans          -> 201 {id,bookId,userId,status:"active"} | 400 | 404 | 409
 *   GET    /api/loans          -> 200 {loans:[...]}
 *   POST   /api/loans/:id/return -> 200 returned loan (idempotent) | 404
 *   GET    /health             -> 200
 */

const express = require('express');
const { RepositoryError } = require('./repository');
const { createCatalogService } = require('./catalog');
const { createLoansModule } = require('./loans');

/**
 * Build the Express app for a given repository.
 * @param {object} repository - repository instance implementing the contract
 *   in src/repository.js.
 * @returns {import('express').Express}
 */
function createApp(repository) {
  const app = express();
  const catalog = createCatalogService(repository);
  const loans = createLoansModule(repository);

  app.use(express.json());

  // Health endpoint (no dependencies).
  app.get('/health', (req, res) => {
    res.status(200).json({ status: 'ok' });
  });

  // Catalog.
  app.post('/api/books', async (req, res, next) => {
    try {
      const book = await catalog.createBook(req.body);
      res.status(201).json(book);
    } catch (err) {
      next(err);
    }
  });

  app.get('/api/books', async (req, res, next) => {
    try {
      const books = await catalog.listBooks();
      res.status(200).json({ books });
    } catch (err) {
      next(err);
    }
  });

  app.get('/api/books/:id', async (req, res, next) => {
    try {
      const book = await catalog.getBook(req.params.id);
      if (book == null) {
        return res.status(404).json({ error: 'Book not found' });
      }
      res.status(200).json(book);
    } catch (err) {
      next(err);
    }
  });

  // Loans.
  app.post('/api/loans', async (req, res, next) => {
    try {
      const { bookId, userId } = req.body == null ? {} : req.body;
      const loan = await loans.borrow(bookId, userId);
      res.status(201).json(loan);
    } catch (err) {
      next(err);
    }
  });

  app.get('/api/loans', async (req, res, next) => {
    try {
      const loanList = await loans.listLoans();
      res.status(200).json({ loans: loanList });
    } catch (err) {
      next(err);
    }
  });

  app.post('/api/loans/:id/return', async (req, res, next) => {
    try {
      const loan = await loans.returnLoan(req.params.id);
      res.status(200).json(loan);
    } catch (err) {
      next(err);
    }
  });

  // Centralised error mapping to HTTP status codes.
  // eslint-disable-next-line no-unused-vars
  app.use((err, req, res, next) => {
    if (err instanceof RepositoryError) {
      const status = Number.isInteger(err.httpStatus) ? err.httpStatus : 500;
      return res.status(status).json({ error: err.message, code: err.code });
    }
    // JSON body parse errors and other unexpected failures.
    if (err && err.type === 'entity.parse.failed') {
      return res.status(400).json({ error: 'Invalid JSON body' });
    }
    res.status(500).json({ error: 'Internal server error' });
  });

  return app;
}

module.exports = { createApp };

'use strict';

/**
 * Loans business module.
 *
 * This is the business layer for borrowing and returning books. The actual
 * transactional/row-lock behaviour (serialising concurrent borrowers on a
 * single client, idempotent returns that restore stock exactly once) lives in
 * the repository adapters so that the PostgreSQL and in-memory implementations
 * share identical semantics. This module depends only on the repository
 * contract injected at construction time, so unit/API tests can drive the
 * same code path with the in-memory adapter while the real PostgreSQL adapter
 * serves the runtime.
 *
 * Domain rules enforced here (and mirrored by every adapter):
 *   - at most one active loan per (bookId, userId);
 *   - a reader may not borrow more copies than remain in stock;
 *   - returnLoan is idempotent: the first active -> returned transition
 *     restores one copy, subsequent returns leave stock unchanged.
 */

const { RepositoryError } = require('./repository');

/**
 * @param {object} repository - repository instance implementing the contract
 *   described in src/repository.js (borrow, returnLoan, listLoans, getLoan).
 */
function createLoansModule(repository) {
  /**
   * Borrow one available copy for a reader.
   * @param {number|string} bookId
   * @param {string} userId - explicitly entered reader ID (demonstration input).
   * @returns {Promise<{id, bookId, userId, status: 'active'}>}
   */
  async function borrow(bookId, userId) {
    if (userId == null || typeof userId !== 'string' || userId.trim() === '') {
      throw new RepositoryError('INVALID_USER_ID', 'userId must be a non-empty string', 400);
    }
    if (!Number.isInteger(bookId) || bookId <= 0) {
      throw new RepositoryError('INVALID_BOOK_ID', 'bookId must be a positive integer', 400);
    }
    return repository.borrow(bookId, userId);
  }

  /**
   * Return a loan. Idempotent: repeated returns do not increment stock again.
   * @param {number|string} loanId
   * @returns {Promise<{id, bookId, userId, status: 'returned'}>}
   */
  async function returnLoan(loanId) {
    return repository.returnLoan(loanId);
  }

  function listLoans() {
    return repository.listLoans();
  }

  function getLoan(loanId) {
    return repository.getLoan(loanId);
  }

  return { borrow, returnLoan, listLoans, getLoan };
}

module.exports = { createLoansModule };

'use strict';

/**
 * Repository interface (contract) shared by the PostgreSQL and in-memory
 * adapters. Every concrete repository must implement all methods below.
 *
 * This module also provides a small set of domain/validation helpers so both
 * adapters (and the business modules that consume them) agree on shapes and
 * error semantics. Business modules depend only on this interface plus the
 * concrete adapter injected at runtime; tests inject the in-memory adapter.
 */

/**
 * Result shape returned by createBook:
 *   { id, title, availableCopies }
 *
 * Result shape returned by listBooks:
 *   Array<{ id, title, availableCopies }>
 *
 * Result shape returned by getBook:
 *   { id, title, availableCopies } | null
 *
 * Result shape returned by createLoan (via borrow):
 *   { id, bookId, userId, status: 'active' }
 *
 * Result shape returned by listLoans / getLoan:
 *   { id, bookId, userId, status }
 *
 * A repository implementation must export an object (class instance or
 * plain object) exposing:
 *
 *   createBook({ title, copies })        -> { id, title, availableCopies }
 *   listBooks()                           -> Array<book>
 *   getBook(id)                           -> book | null
 *   borrow(bookId, userId)               -> { id, bookId, userId, status } or throw
 *   listLoans()                           -> Array<loan>
 *   getLoan(id)                           -> loan | null
 *   returnLoan(id)                        -> loan with status 'returned' or throw
 *
 * Semantics (kept identical across adapters):
 *   - borrow throws a typed error when no remaining stock or a duplicate
 *     active loan exists (caller maps to 409).
 *   - returnLoan is idempotent: returning an already-returned loan does not
 *     restore stock a second time.
 */

class RepositoryError extends Error {
  /**
   * @param {string} code - stable machine code ('NOT_FOUND', 'NO_STOCK',
   *   'DUPLICATE_LOAN', 'INVALID_STATE').
   * @param {string} message - human-readable message.
   * @param {number} [httpStatus] - suggested HTTP status.
   */
  constructor(code, message, httpStatus) {
    super(message);
    this.name = 'RepositoryError';
    this.code = code;
    this.httpStatus = httpStatus;
  }
}

/**
 * Validate fields shared by both adapters so behaviour is consistent.
 *
 * @param {string} title
 * @param {*} copies
 */
function assertBookInput(title, copies) {
  if (typeof title !== 'string' || title.trim() === '') {
    throw new RepositoryError('INVALID_TITLE', 'Title must be a non-empty string', 400);
  }
  if (!Number.isInteger(copies) || copies <= 0) {
    throw new RepositoryError('INVALID_COPIES', 'Copies must be a positive integer', 400);
  }
}

/**
 * Normalise a book row (internal storage) into the public shape.
 * @param {{id: number|string, title: string, copies: number}} row
 */
function toBook(row) {
  return {
    id: row.id,
    title: row.title,
    availableCopies: row.copies,
  };
}

/**
 * Normalise a loan row into the public shape.
 * @param {{id: number|string, bookId: number|string, userId: string, status: string}} row
 */
function toLoan(row) {
  return {
    id: row.id,
    bookId: row.bookId,
    userId: row.userId,
    status: row.status,
  };
}

module.exports = {
  RepositoryError,
  assertBookInput,
  toBook,
  toLoan,
};

'use strict';

/**
 * PostgreSQL repository implementing the shared repository contract in
 * src/repository.js. Borrowing and returning run inside a transaction on a
 * single client with row locks so concurrent borrowers cannot push available
 * copies below zero and concurrent returns never restore stock more than once.
 */

const {
  RepositoryError,
  assertBookInput,
  toBook,
  toLoan,
} = require('./repository');

const BOOK_COLUMNS = 'id, title, copies';

function rowToBook(row) {
  return toBook(row);
}

function rowToLoan(row) {
  return toLoan({
    id: row.id,
    bookId: row.book_id,
    userId: row.user_id,
    status: row.status,
  });
}

class PgRepository {
  /**
   * @param {import('pg').Pool} pool - PostgreSQL connection pool.
   */
  constructor(pool) {
    this.pool = pool;
  }

  async createBook({ title, copies }) {
    assertBookInput(title, copies);
    try {
      const result = await this.pool.query(
        'INSERT INTO books (title, copies) VALUES ($1, $2) RETURNING ' + BOOK_COLUMNS,
        [title, copies]
      );
      return rowToBook(result.rows[0]);
    } catch (err) {
      if (err.code === '23514') {
        throw new RepositoryError('INVALID_COPIES', 'Copies must be a positive integer', 400);
      }
      throw err;
    }
  }

  async listBooks() {
    const result = await this.pool.query(
      'SELECT ' + BOOK_COLUMNS + ' FROM books ORDER BY id'
    );
    return result.rows.map(rowToBook);
  }

  async getBook(id) {
    const result = await this.pool.query(
      'SELECT ' + BOOK_COLUMNS + ' FROM books WHERE id = $1',
      [id]
    );
    return result.rows.length === 0 ? null : rowToBook(result.rows[0]);
  }

  /**
   * Borrow one available copy for a reader. Uses a transaction and FOR UPDATE
   * row lock on the book to serialise concurrent borrowers.
   */
  async borrow(bookId, userId) {
    if (typeof userId !== 'string' || userId.trim() === '') {
      throw new RepositoryError('INVALID_USER_ID', 'userId must be a non-empty string', 400);
    }

    const client = await this.pool.connect();
    try {
      await client.query('BEGIN');

      const bookResult = await client.query(
        'SELECT id, title, copies FROM books WHERE id = $1 FOR UPDATE',
        [bookId]
      );
      if (bookResult.rows.length === 0) {
        throw new RepositoryError('NOT_FOUND', 'Book not found', 404);
      }
      const book = bookResult.rows[0];

      if (book.copies <= 0) {
        throw new RepositoryError('NO_STOCK', 'No available copies', 409);
      }

      const duplicate = await client.query(
        "SELECT id FROM loans WHERE book_id = $1 AND user_id = $2 AND status = 'active'",
        [bookId, userId]
      );
      if (duplicate.rows.length > 0) {
        throw new RepositoryError('DUPLICATE_LOAN', 'Reader already has an active loan', 409);
      }

      const loanResult = await client.query(
        "INSERT INTO loans (book_id, user_id, status) VALUES ($1, $2, 'active') RETURNING id, book_id, user_id, status",
        [bookId, userId]
      );

      await client.query('UPDATE books SET copies = copies - 1 WHERE id = $1', [bookId]);

      await client.query('COMMIT');
      return rowToLoan(loanResult.rows[0]);
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  }

  async listLoans() {
    const result = await this.pool.query(
      'SELECT id, book_id, user_id, status FROM loans ORDER BY id'
    );
    return result.rows.map(rowToLoan);
  }

  async getLoan(id) {
    const result = await this.pool.query(
      'SELECT id, book_id, user_id, status FROM loans WHERE id = $1',
      [id]
    );
    return result.rows.length === 0 ? null : rowToLoan(result.rows[0]);
  }

  /**
   * Return a loan. Idempotent: returning an already-returned loan leaves stock
   * untouched. The transition from active -> returned increments stock exactly
   * once inside a transaction with a row lock.
   */
  async returnLoan(id) {
    const client = await this.pool.connect();
    try {
      await client.query('BEGIN');

      const loanResult = await client.query(
        'SELECT id, book_id, user_id, status FROM loans WHERE id = $1 FOR UPDATE',
        [id]
      );
      if (loanResult.rows.length === 0) {
        throw new RepositoryError('NOT_FOUND', 'Loan not found', 404);
      }
      const loan = loanResult.rows[0];

      if (loan.status === 'returned') {
        await client.query('COMMIT');
        return rowToLoan(loan);
      }

      await client.query(
        "UPDATE loans SET status = 'returned', returned_at = now() WHERE id = $1",
        [id]
      );
      await client.query('UPDATE books SET copies = copies + 1 WHERE id = $1', [loan.book_id]);

      await client.query('COMMIT');

      const updated = await this.pool.query(
        'SELECT id, book_id, user_id, status FROM loans WHERE id = $1',
        [id]
      );
      return rowToLoan(updated.rows[0]);
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  }
}

module.exports = { PgRepository };

'use strict';

/**
 * Catalog business module.
 *
 * Thin business layer over the repository contract (src/repository.js). The
 * repository adapters already enforce shared validation and error semantics;
 * this module expresses the catalog use cases explicitly so routes bind to
 * stable behaviour rather than raw adapter calls:
 *
 *   - createBook: create a title with a positive number of copies.
 *   - listBooks:  list titles with their currently available copies.
 *   - getBook:    fetch one title, reporting a 404 when it does not exist.
 */

const { RepositoryError } = require('./repository');

/**
 * @param {object} repo - repository implementing the shared contract in
 *   src/repository.js (createBook, listBooks, getBook, borrow, listLoans,
 *   getLoan, returnLoan).
 */
function createCatalogService(repo) {
  /**
   * Create a book. Delegates validation of the title/copies to the repository,
   * which throws RepositoryError with an HTTP status on invalid input.
   * @param {{title: string, copies: number}} input
   * @returns {{id: number, title: string, availableCopies: number}}
   */
  async function createBook(input) {
    const { title, copies } = input == null ? {} : input;
    return repo.createBook({ title, copies });
  }

  /**
   * List all books with available copies.
   * @returns {Promise<Array<{id: number, title: string, availableCopies: number}>>}
   */
  async function listBooks() {
    return repo.listBooks();
  }

  /**
   * Get a single book, or null when missing.
   * @param {number|string} id
   * @returns {{id: number, title: string, availableCopies: number}|null}
   */
  async function getBook(id) {
    return repo.getBook(id);
  }

  return { createBook, listBooks, getBook };
}

module.exports = {
  createCatalogService,
  RepositoryError,
};

'use strict';

/**
 * PostgreSQL schema bootstrap for the library borrowing application.
 *
 * Idempotent: CREATE TABLE IF NOT EXISTS so repeated startup never fails.
 * Seed data is inserted only when the books table is empty, so user-created
 * books are preserved across restarts.
 */

const SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS books (
  id BIGSERIAL PRIMARY KEY,
  title TEXT NOT NULL,
  copies INTEGER NOT NULL CHECK (copies >= 0)
);

CREATE TABLE IF NOT EXISTS loans (
  id BIGSERIAL PRIMARY KEY,
  book_id BIGINT NOT NULL REFERENCES books(id),
  user_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('active', 'returned')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  returned_at TIMESTAMPTZ
);

CREATE UNIQUE INDEX IF NOT EXISTS loans_active_unique
  ON loans (book_id, user_id)
  WHERE status = 'active';
`;

const SEED_BOOKS = [
  { title: 'The Great Gatsby', copies: 3 },
  { title: '1984', copies: 2 },
  { title: 'To Kill a Mockingbird', copies: 1 },
];

/**
 * Create tables and indexes idempotently, then seed books only when empty.
 *
 * @param {import('pg').Pool} pool - PostgreSQL connection pool.
 */
async function bootstrap(pool) {
  await pool.query(SCHEMA_SQL);

  const existing = await pool.query('SELECT COUNT(*)::int AS count FROM books');
  if (existing.rows[0].count > 0) {
    return;
  }

  for (const book of SEED_BOOKS) {
    await pool.query('INSERT INTO books (title, copies) VALUES ($1, $2)', [
      book.title,
      book.copies,
    ]);
  }
}

module.exports = { bootstrap, SEED_BOOKS };

'use strict';

/**
 * In-memory repository implementing the shared repository contract in
 * src/repository.js. Intended for unit/API tests so npm test runs without a
 * live PostgreSQL. Behaviour (validation, error codes, idempotent returns)
 * mirrors the PostgreSQL adapter so the business modules and routes are
 * exercised identically.
 */

const {
  RepositoryError,
  assertBookInput,
  toBook,
  toLoan,
} = require('./repository');

class MemoryRepository {
  constructor() {
    this.books = new Map(); // id -> { id, title, copies }
    this.loans = new Map(); // id -> { id, bookId, userId, status }
    this.nextBookId = 1;
    this.nextLoanId = 1;
  }

  createBook({ title, copies }) {
    assertBookInput(title, copies);
    const id = this.nextBookId++;
    const row = { id, title, copies };
    this.books.set(id, row);
    return toBook(row);
  }

  listBooks() {
    return [...this.books.values()].sort((a, b) => a.id - b.id).map(toBook);
  }

  getBook(id) {
    const row = this.books.get(Number(id));
    return row == null ? null : toBook(row);
  }

  borrow(bookId, userId) {
    if (typeof userId !== 'string' || userId.trim() === '') {
      throw new RepositoryError('INVALID_USER_ID', 'userId must be a non-empty string', 400);
    }

    const book = this.books.get(Number(bookId));
    if (book == null) {
      throw new RepositoryError('NOT_FOUND', 'Book not found', 404);
    }
    if (book.copies <= 0) {
      throw new RepositoryError('NO_STOCK', 'No available copies', 409);
    }

    for (const loan of this.loans.values()) {
      if (loan.bookId === book.id && loan.userId === userId && loan.status === 'active') {
        throw new RepositoryError('DUPLICATE_LOAN', 'Reader already has an active loan', 409);
      }
    }

    const id = this.nextLoanId++;
    const loan = { id, bookId: book.id, userId, status: 'active' };
    this.loans.set(id, loan);
    book.copies -= 1;
    return toLoan(loan);
  }

  listLoans() {
    return [...this.loans.values()].sort((a, b) => a.id - b.id).map(toLoan);
  }

  getLoan(id) {
    const row = this.loans.get(Number(id));
    return row == null ? null : toLoan(row);
  }

  returnLoan(id) {
    const loan = this.loans.get(Number(id));
    if (loan == null) {
      throw new RepositoryError('NOT_FOUND', 'Loan not found', 404);
    }

    if (loan.status === 'returned') {
      return toLoan(loan);
    }

    loan.status = 'returned';
    const book = this.books.get(loan.bookId);
    if (book != null) {
      book.copies += 1;
    }
    return toLoan(loan);
  }
}

module.exports = { MemoryRepository };

